mapper.select:
SELECT M.MENTORING_NUM, M.TITLE, M.CONTENT, M.REG_DATE, M.VIEW_COUNT, T.TEAM_NUM, T.INTRO, W.WEEKLY_NUM, W.WEEK_NAME, U.USER_ID
FROM TBL_MENTORING M JOIN TBL_TEAM T ON M.TEAM_NUM = T.TEAM_NUM JOIN TBL_WEEKLY W ON M.WEEKLY_NUM = W.WEEKLY_NUM JOIN TBL_USER U ON M.USER_ID = U.USER_ID
WHERE M.MENTORING_NUM = #{value}

mapper.update:
UPDATE TBL_MENTORING
SET TITLE = #{title}, CONTENT = #{content}
WHERE MENTORING_NUM = #{mentoringNum}

UPDATE TBL_MENTORING
SET VIEW_COUNT = VIEW_COUNT + 1
WHERE MENTORING_NUM = #{value}

mapper.select:
SELECT FILE_NUM, SUBSTR(FILE_NAME, INSTR(FILE_NAME, '_') + 1) AS FILE_NAME, FILE_NAME AS FILES, MENTORING_NUM
FROM TBL_MENTORING_FILE
WHERE MENTORING_NUM = #{value}

SELECT T.TEAM_NUM, T.TEAM_NAME, T.YEAR, T.TERM, T.USER_ID, T.INTRO, T.REG_DATE
FROM TBL_TEAM T
WHERE T.YEAR = #{year}
AND T.TERM = #{term}
AND (
T.USER_ID = #{userId}
OR EXISTS (
SELECT 1
FROM TBL_TEAM_MEMBER TM
WHERE TM.TEAM_NUM = T.TEAM_NUM
AND TM.USER_ID = #{userId}
AND TM.PART IN ('M', 'S')
)
)
ORDER BY T.TEAM_NUM DESC

SELECT COUNT(*)
FROM TBL_MENTORING_COMT
WHERE MENTORING_NUM = #{value}
